package app.service;

import app.domain.Token;
import app.domain.TokenRepository;
import app.domain.TokenType;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;
import java.util.*;

@Service
public class TokenService {
    private final TokenRepository tokenRepository;

    public TokenService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    public Token createToken(Long userId, TokenType type, String tokenValue, Instant expiresAt) {
        Token token = new Token();
        token.setUserId(userId);
        token.setTokenValue(tokenValue);
        token.setTokenType(type);
        token.setExpiresAt(expiresAt);
        token.setIssuedAt(Instant.now());
        token.setRevoked(false);
        token.setConsumed(false);
        return tokenRepository.save(token);
    }

    public Optional<Token> findToken(String tokenValue, Long userId) {
        return tokenRepository.findByTokenValueAndUserId(tokenValue, userId);
    }

    public List<Token> findTokensByUserIdAndType(Long userId, TokenType type) {
        return tokenRepository.findAllByUserIdAndTokenType(userId, type);
    }

    public List<Token> findTokensByUserId(Long userId) {
        return tokenRepository.findAllByUserId(userId);
    }

    public void revokeToken(Long tokenId) {
        Token token = tokenRepository.findById(tokenId).orElseThrow(() -> new RuntimeException("Token not found"));
        token.setRevoked(true);
        tokenRepository.save(token);
    }

    public void markAsConsumed(Long tokenId) {
        Token token = tokenRepository.findById(tokenId).orElseThrow(() -> new RuntimeException("Token not found"));
        token.setConsumed(true);
        tokenRepository.save(token);
    }

    public void deleteToken(Long tokenId) {
        tokenRepository.deleteById(tokenId);
    }

    public void deleteTokensByUserId(Long userId) {
        List<Token> tokens = findTokensByUserId(userId);
        for (Token token : tokens) {
            deleteToken(token.getId());
        }
    }

    public boolean isValidToken(String tokenValue, Long userId) {
        Optional<Token> tokenOpt = findToken(tokenValue, userId);
        if (tokenOpt.isPresent()) {
            Token token = tokenOpt.get();
            if (token.isRevoked()) return false;
            if (token.isConsumed()) return false;
            if (token.getExpiresAt().isBefore(Instant.now())) return false;
            return true;
        }
        return false;
    }

    public void consumeToken(String tokenValue, Long userId) {
        Optional<Token> tokenOpt = findToken(tokenValue, userId);
        if (tokenOpt.isPresent()) {
            Token token = tokenOpt.get();
            if (token.isRevoked() || token.isConsumed() || token.getExpiresAt().isBefore(Instant.now())) {
                throw new IllegalStateException("Token is already revoked, consumed, or expired");
            }
            token.setConsumed(true);
            tokenRepository.save(token);
        } else {
            throw new IllegalStateException("Token not found");
        }
    }

    public boolean hasOpenTokenForUser(Long userId, TokenType type) {
        List<Token> tokens = findTokensByUserIdAndType(userId, type);
        for (Token token : tokens) {
            if (!token.isRevoked() && !token.isConsumed() && token.getExpiresAt().isAfter(Instant.now())) {
                return true;
            }
        }
        return false;
    }

    public void rotateRefreshToken(Long userId, String oldTokenValue, String newTokenValue) {
        // Find and revoke the old refresh token
        Optional<Token> oldTokenOpt = findToken(oldTokenValue, userId);
        if (oldTokenOpt.isPresent()) {
            Token oldToken = oldTokenOpt.get();
            if (oldToken.getTokenType() == TokenType.REFRESH_TOKEN && !oldToken.isRevoked()) {
                oldToken.setRevoked(true);
                tokenRepository.save(oldToken);
            }
        }

        // Create a new refresh token
        Instant newExpires = Instant.now().plusSeconds(86400); // 24 hours
        createToken(userId, TokenType.REFRESH_TOKEN, newTokenValue, newExpires);
    }

    public String generateAccessToken(Long userId) {
        String tokenValue = UUID.randomUUID().toString();
        Instant expires = Instant.now().plusSeconds(600); // 10 minutes
        createToken(userId, TokenType.ACCESS_TOKEN, tokenValue, expires);
        return tokenValue;
    }

    public String generateOneTimeToken(Long userId) {
        String tokenValue = UUID.randomUUID().toString();
        Instant expires = Instant.now().plusSeconds(300); // 5 minutes
        createToken(userId, TokenType.ONE_TIME_TOKEN, tokenValue, expires);
        return tokenValue;
    }

    public String generateRefreshToken(Long userId) {
        String tokenValue = UUID.randomUUID().toString();
        Instant expires = Instant.now().plusSeconds(86400); // 24 hours
        createToken(userId, TokenType.REFRESH_TOKEN, tokenValue, expires);
        return tokenValue;
    }

    public void cleanupTokens() {
        List<Token> allTokens = tokenRepository.findAll();
        int deleted = 0;
        for (Token token : allTokens) {
            if (token.isRevoked() || token.isConsumed() || token.getExpiresAt().isBefore(Instant.now())) {
                tokenRepository.deleteById(token.getId());
                deleted++;
            }
        }
        System.out.println("[CLEANUP] Deleted " + deleted + " tokens");
    }
}
EOF"}

