package app.controller;

import app.domain.TokenType;
import app.service.TokenService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

@RestController
@RequestMapping("/api/auth")
public class AuthController {
    private final TokenService tokenService;

    @Autowired
    public AuthController(TokenService tokenService) {
        this.tokenService = tokenService;
    }

    @PostMapping("/login")
    public ResponseEntity<Map<String, String>> login(@RequestBody LoginRequest request) {
        if (request.getUsername() == null || request.getUsername().isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Username is required");
        }
        if (request.getPassword() == null || request.getPassword().isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Password is required");
        }

        Long userId = 1L; // Simplified - in reality we'd look up by username

        String accessToken = tokenService.generateAccessToken(userId);
        String oneTimeToken = tokenService.generateOneTimeToken(userId);
        String refreshToken = tokenService.generateRefreshToken(userId);

        HttpHeaders headers = new HttpHeaders();
        headers.add("Set-Cookie", "refreshToken=" + refreshToken + "; HttpOnly; Max-Age=86400; Path=/" );

        Map<String, String> response = new HashMap<>();
        response.put("accessToken", accessToken);
        response.put("oneTimeToken", oneTimeToken);

        return new ResponseEntity<>(response, headers, HttpStatus.OK);
    }

    @PostMapping("/renew")
    public ResponseEntity<Map<String, String>> renew(@CookieValue(value = "refreshToken", required = false) String cookieRefreshToken,
                                                    @RequestHeader(value = "refreshToken", required = false) String headerRefreshToken) {
        String refreshTokenValue = cookieRefreshToken != null ? cookieRefreshToken : headerRefreshToken;
        if (refreshTokenValue == null || refreshTokenValue.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Missing refresh token");
        }

        // Find the refresh token for the user
        Optional<Token> refreshTokenOpt = tokenService.findToken(refreshTokenValue, 1L);
        if (!refreshTokenOpt.isPresent()) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Invalid refresh token");
        }
        Token refreshToken = refreshTokenOpt.get();

        if (refreshToken.getTokenType() != TokenType.REFRESH_TOKEN) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Invalid refresh token type");
        }

        if (refreshToken.isRevoked()) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Revoked refresh token");
        }

        if (refreshToken.getExpiresAt().isBefore(Instant.now())) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Expired refresh token");
        }

        // Revoke the old refresh token atomically
        tokenService.revokeToken(refreshToken.getId());

        // Issue new tokens
        String newAccessToken = tokenService.generateAccessToken(1L);
        String newRefreshToken = tokenService.generateRefreshToken(1L);

        // Save the new refresh token
        tokenService.createToken(1L, TokenType.REFRESH_TOKEN, newRefreshToken, Instant.now().plusSeconds(86400));

        HttpHeaders headers = new HttpHeaders();
        headers.add("Set-Cookie", "refreshToken=" + newRefreshToken + "; HttpOnly; Max-Age=86400; Path=/" );

        Map<String, String> response = new HashMap<>();
        response.put("accessToken", newAccessToken);

        return new ResponseEntity<>(response, headers, HttpStatus.OK);
    }

    @PostMapping("/validate-token")
    public ResponseEntity<Map<String, Boolean>> validateToken(@RequestBody Map<String, String> request) {
        String tokenValue = request.get("token");
        if (tokenValue == null || tokenValue.isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false));
        }

        try {
            tokenService.consumeToken(tokenValue, 1L);
            return ResponseEntity.ok(Map.of("valid", true));
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("valid", false));
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<Map<String, String>> logout(@RequestHeader("Authorization") String authorizationHeader) {
        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Missing or invalid access token");
        }
        String accessToken = authorizationHeader.substring(7);

        // In a real system, we'd validate the access token exists and is not revoked
        // Here we just invalidate all tokens for the user
        tokenService.deleteTokensByUserId(1L);

        Map<String, String> response = new HashMap<>();
        response.put("message", "Logged out successfully");
        return ResponseEntity.ok(response);
    }

    // Inner class for login request
    static class LoginRequest {
        private String username;
        private String password;

        public String getUsername() {
            return username;
        }

        public void setUsername(String username) {
            this.username = username;
        }

        public String getPassword() {
            return password;
        }

        public void setPassword(String password) {
            this.password = password;
        }
    }
}
