package app.scheduler;

import app.domain.TokenRepository;
import app.service.TokenService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.time.Instant;
import java.util.List;
import java.util.stream.Collectors;

@Component
public class CleanupTask {
    private final TokenRepository tokenRepository;
    private final TokenService tokenService;

    @Autowired
    public CleanupTask(TokenRepository tokenRepository, TokenService tokenService) {
        this.tokenRepository = tokenRepository;
        this.tokenService = tokenService;
    }

    @Scheduled(fixedRate = 10000) // Every 10 seconds
    public void runCleanup() {
        List<Token> allTokens = tokenRepository.findAll();
        int deleted = 0;
        for (Token token : allTokens) {
            if (token.isRevoked() || token.isConsumed() || token.getExpiresAt().isBefore(Instant.now())) {
                tokenRepository.deleteById(token.getId());
                deleted++;
            }
        }
        System.out.println("[CLEANUP] Deleted " + deleted + " tokens");
    }
}
